function PipelineVCamController:__init()
    self.controller = nil

    self._playerFollow = nil -- Transform

    self._lookAtIsMoving = false

    self._lastLookAtPosition = Vector3.zero
    self._movingDetectFrameCount = 0 -- int
    self._movingDetectTimer = 0.0 
       
    self._vcamDirection = 0 -- int

    self.originOrbits = {}

    self.originTrackedObjectOffsets = {}

    ------
    self.inApproachMode = InApproachMode.Entering

    self._isInTrigger = false -- 是否在任意一个 trigger 碰撞体内
    self.isInCave = false -- 从进入通道的 trigger, 到离开通道的 trigger 
    self.isInsideApproach = false   -- 是否在 approach 球体区域内

    self.currentApproachCenterPos = Vector3.zero
    self.currentApproachRadius = 1.0

    self.isInLerping = false -- 

    self.lerpedMidOrbit = Orbit( 0.2, 1.3 ) -- 随便写个初始值
    self.lerpedTrackedObjectOffsetY = 0.25 -- 随便写个初始值

    self.originMidOrbitHeight = nil  -- Float, 不要在此写值
    self.originMidOrbitRadius = nil -- Float, 不要在此写值
    self.originTrackedObjectOffsetY = nil -- Float, 不要在此写值
end


