end


function PipelineVCamController:Awake()
    KTool.SetActive(self.controller.gameObject, true);
    self.transform = self.controller.gameObject.transform

    assert( self.vcam and self.pipelinePath and self.pipelineLookAtPoint )

    self._isLocking = false
    self._isNeedRunUpdate = false
    self._point = 0
    self._positionUnits = PositionUnits.Distance

    self._vcamDollyComponent = DreamSpaceLuaUtils.GetCinemachineComponent( self.vcam, typeof(CinemachineTrackedDolly) ) 
end




function PipelineVCamController:Start()
    KTool.SetActive(self.controller.gameObject, true)

    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end

    -- ----
    local luaParams = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( luaParams )

    -- must after Awake()
    self.mCamera = DreamSpaceCamera.GetMainCamera()
    self._mainCameraTF = self.mCamera.transform


    self.canTriggerTag = LuaParametersReader.Read( luaParams, "canTriggerTag", LuaParametersType.String ) -- "Player", 可以触发事件的物体Tag
    self.blendDuration = LuaParametersReader.Read( luaParams, "blendDuration", LuaParametersType.Float ) -- 0.5,  从自由相机切换到管道相机的融合时间

    self.normalPositionOffset = LuaParametersReader.Read( luaParams, "normalPositionOffset", LuaParametersType.Float ) -- -3, 正常情况下相机距离玩家的距离
    self.cornerPositionOffset = LuaParametersReader.Read( luaParams, "cornerPositionOffset", LuaParametersType.Float ) -- -1, 角落遮挡时相机距离玩家的距离
    self.normalPathOffsetY    = LuaParametersReader.Read( luaParams, "normalPathOffsetY", LuaParametersType.Float ) -- 1, 正常情况下相机离地的高度
    self.cornerPathOffsetY    = LuaParametersReader.Read( luaParams, "cornerPathOffsetY", LuaParametersType.Float ) -- 0.7, 角落遮挡时相机离地的高度


    self.autoCornerDetect   = LuaParametersReader.Read( luaParams, "autoCornerDetect", LuaParametersType.Bool )
    self.closeToPlayerSpeed = LuaParametersReader.Read( luaParams, "closeToPlayerSpeed", LuaParametersType.Float ) -- 0.2, 角落遮挡时相机靠近玩家的速度
    self.movingDetectTime   = LuaParametersReader.Read( luaParams, "movingDetectTime", LuaParametersType.Float ) -- 0.2, 检测玩家是否在移动的时间间隔
    self.movingDetectError  = LuaParametersReader.Read( luaParams, "movingDetectError", LuaParametersType.Float ) -- 0.1, 检测玩家是否在移动的距离误差


    -- 猫进洞后, freelook 相机的参数:
    self.targetMidOrbitHeight       = LuaParametersReader.Read( luaParams, "targetMidOrbitHeight", LuaParametersType.Float ) -- 0.2
    self.targetMidOrbitRadius       = LuaParametersReader.Read( luaParams, "targetMidOrbitRadius", LuaParametersType.Float ) -- 1.3
    self.targetTrackedObjectOffsetY = LuaParametersReader.Read( luaParams, "targetTrackedObjectOffsetY", LuaParametersType.Float ) -- 0.25

    self.leaveSmoothTime = LuaParametersReader.Read( luaParams, "leaveSmoothTime", LuaParametersType.Float ) -- 2.0, 猫离开洞口时, freelook相机参数平滑恢复的时长


    ------
    local idComps = self.transform:GetComponentsInChildren(typeof(ID),true) -- 包含自己
    for i=0, idComps.Length-1 do 
        local idComp = idComps[i]
        
        if idComp.stringId == "Trigger" then 
            local triggerComp = DreamSpaceLuaUtils.GetLuaScr(idComp.gameObject, "Game.DreamSpace.PipelineVCam.PipelineVCamTrigger" )
            assert( triggerComp )
            triggerComp:SetController(self)

        elseif idComp.stringId == "Lock" then
            local lockComp = DreamSpaceLuaUtils.GetLuaScr(idComp.gameObject, "Game.DreamSpace.PipelineVCam.PipelineVCamLock" )
            assert( lockComp )
            lockComp:SetController(self)

        elseif idComp.stringId == "Approach" then
            local approachComp = DreamSpaceLuaUtils.GetLuaScr(idComp.gameObject, "Game.DreamSpace.PipelineVCam.PipelineVCamApproach" )
            assert( approachComp )
            approachComp:SetController(self)
        end
    end

    ---
    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start( self.DelayInit, self )
end


function PipelineVCamController:DelayInit()
    coroutine.yield(Yielders.EndOfFrame) -- 等一帧
    
    self._playerFollow = nil

    self.followTF = nil
    local vcamControllerTF = nil
    -- 只会查找若干次，还是找不到就放弃本功能
    for i = 1, DreamSpaceStates.DelayInitWaitFrames do
        self._playerFollow = GlobalsInDreamSpace.FindComponent("vTargetFollow") -- tf

        self.vcam3rdPersonFollow = GlobalsInDreamSpace.FindComponent("vcam3rdPersonFollow") -- CinemachineVirtualCamera
        self.followTF = GlobalsInDreamSpace.FindComponent("vTargetFollow") -- Transform

        vcamControllerTF = GlobalsInDreamSpace.FindComponent("vcamControllerTF") -- Transform

        if isNotNull(self._playerFollow) and isNotNull(self.vcam3rdPersonFollow) and self.followTF and vcamControllerTF then
            break
        end
        coroutine.yield(Yielders.EndOfFrame)
    end

    assert( self._playerFollow )
    assert( self.vcam3rdPersonFollow )
    assert( self.followTF ) -- 既能表达 猫pos, 也能表达 猫 forward
    assert( vcamControllerTF )

    ---@type VCam3rdPersonFollowController
    self.vcam3rdPersonFollowControllerEnv = DreamSpaceLuaUtils.GetLuaScr(vcamControllerTF.gameObject, "Game.DreamSpace.CharacterController.VCam3rdPersonFollowController" )
    assert( self.vcam3rdPersonFollowControllerEnv )



end




function PipelineVCamController:OnDestroy()

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    DreamSpaceLuaUtils.StopCoroutine( self.co_2 )
    self.co_1 = nil
    self.co_2 = nil

    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


function PipelineVCamController:Update()

    self:UpdateWhenInApproach()

    if not self._isNeedRunUpdate then
        return
    end

    -- 等待 虚拟相机转换彻底结束, vcam3rdPersonFollow 彻底待机后, 才给它赋值
    if self.vcam3rdPersonFollowControllerEnv:IsVCamLive() == false then  
        --print("-- in inn cave --")
        self.vcam3rdPersonFollowControllerEnv:SetLookAt2_ManualTF( self.vcam.transform.forward ) -- !!!!!!!
    end 


    self:CalculateLookAt()

    if self.autoCornerDetect then
        self:DetectIsLookAtMoving()
        if self._lookAtIsMoving then
            self:CloseToPlayer( self:CornerDetect() )
        end
    end
end



-- =========================================== Self ================================================ --


-- 整个隧道的 入口
function PipelineVCamController:Enable(which, direction)
    if not which:CompareTag(self.canTriggerTag) then
        return
    end
    self._isInTrigger = true

    if self._isLocking then
        return
    end
    -- 由于 lock 的辅助, 只有通道入口的 trigger 会执行后续内容

    DreamSpaceStates.LockViewRotate_ByFlag(DreamSpaceStates.InputLockState.Lock) -- !!! 锁旋转

    self.isInCave = true
    self:SetEnterDirection(direction)

    InputManager.SetMoveInputMagnitudeConstraint( nil, 0.2 ) -- 进入通道后, 只能走路
    DreamSpaceStates.environmentType = DreamSpaceStates.EnvironmentType.InPipe


    self.vcam.Follow = self._playerFollow 
    CinemachineBrainUtility.SetDefaultBlendDefinition(CinemachineBlendDefinition.Style.EaseInOut, self.blendDuration)

    self.vcam.Priority = priorityMax  -- 切换 vcan
    self._isNeedRunUpdate = true

end


-- 整个隧道的 出口
function PipelineVCamController:Disable( trigger_, which_, closedPos_ )
    if not which_:CompareTag(self.canTriggerTag) then
        return
    end
    self._isInTrigger = false

    if self._isLocking then
        return
    end
    -- 由于 lock 的辅助, 只有通道出口的 trigger 会执行后续内容

    self.isInCave = false

    InputManager.SetMoveInputMagnitudeConstraint( 0.0, 1.0 ) -- 解除 "只能走路" 的限制
    DreamSpaceStates.environmentType = DreamSpaceStates.EnvironmentType.Default


    self.vcam.Priority = priorityMin
    self._isNeedRunUpdate = false

    DreamSpaceStates.LockViewRotate_ByFlag(DreamSpaceStates.InputLockState.Unlock) -- !!! 释放旋转
end



function PipelineVCamController:Lock(which)
    if not which:CompareTag(self.canTriggerTag) then
        return
    end
    self._isLocking = true
end


function PipelineVCamController:Unlock(which)
    if not which:CompareTag(self.canTriggerTag) then
        return
    end
    self._isLocking = false
end


---@param direction number 每个轨道有预定入口出口, 从入口进此值为 1, 从出口进, 此值为 -1
function PipelineVCamController:SetEnterDirection(direction)
    -- 计算玩家和相机的方向正反
    local playerAndCameraDirection = self:CalculatePlayerCameraDirection() -- 角色方向 和 相机方向若在一个半球, 为1, 否则为 -1
    self._vcamDirection = direction * playerAndCameraDirection

    -- 根据进入方向决定position offset的方向
    local val = self.normalPositionOffset * self._vcamDirection

    -- 必须要这么设置, 否则会失效
    local dolly = self._vcamDollyComponent.m_AutoDolly
    dolly.m_PositionOffset = val 
    self._vcamDollyComponent.m_AutoDolly = dolly
end



function PipelineVCamController:CalculateLookAt()
    local prevPos = self.pipelinePath:ToNativePathUnits(self._point, self._positionUnits)
    self._point = self.pipelinePath:FindClosestPoint(
        self._playerFollow.position, Mathf.FloorToInt(prevPos), 2, 5)   
    self._point = self.pipelinePath:FromPathNativeUnits(self._point, self._positionUnits)
    local newPos = self.pipelinePath:EvaluatePositionAtUnit(self._point, self._positionUnits)
    --print( "newPos = " .. newPos:ToString() )
    self.pipelineLookAtPoint.position = newPos
end




-- 现在  followTF 在 猫后腿部, 改拿一个靠近猫前身的 pos
function PipelineVCamController:GetRoleHeadPos()
    return self.followTF.position + self.followTF.forward * 0.0
end



-- 猫进入 approach 区域时:
function PipelineVCamController:InApproach(which, approachCenterPos_, colliderRadius_ )
    if not which:CompareTag(self.canTriggerTag) then
        return
    end 

    self.inApproachMode = (self.isInCave == true) and InApproachMode.Leaving or InApproachMode.Entering
    self.isInLerping = true

    -------
    self.isInsideApproach = true
    self.currentApproachCenterPos = approachCenterPos_
    self.currentApproachRadius = colliderRadius_

    self.vcam3rdPersonFollowControllerEnv:SetCustomVCamParams({ height = 0.15, radius = 1.3, shoulderOffset = Vector3.zero })
    
    if self.isInCave == true then 
        return
    end 
    -- 只有在进洞时, 下方代码才被执行;  在出洞时, 则不会;


end



function PipelineVCamController:OutApproach(which)
    if not which:CompareTag(self.canTriggerTag) then
        return
    end
    self.isInsideApproach = false
end




-- 当 猫进入 approach 区域内后, 需要进行的逐帧计算
function PipelineVCamController:UpdateWhenInApproach()
    if self.isInsideApproach == false then 
        return
    end 

    -- 屏蔽掉位于通道内的 半个球体:
    if self.isInCave == true then 
        return
    end

    local distance = Vector3.ProjectOnPlane( self:GetRoleHeadPos() - self.currentApproachCenterPos, Vector3.up ).magnitude
    local t = distance / self.currentApproachRadius -- [1->0], 由于 猫collider 也有半径, 所以这个 t 值是会大于 1 的 
    t = Mathf.Clamp01( KTool.Remap( 0.3, 1, 0.0, 1.0, t ) ) -- [0,0.3] 都认为是 "完全接近洞口" 了

    -- 足够靠近洞口时把 相机与墙壁碰撞的 damping 值调大, 要不然后面从 vcam3rdPersonFollow 切换为 轨道vcam 时会出现抖动 (vcam3rdPersonFollow 被墙壁挡住了)
    if t < 0.1 then 
        self.vcam3rdPersonFollowControllerEnv:SetDampingIntoCollision()
    else
        self.vcam3rdPersonFollowControllerEnv:ResetDampingIntoCollision()
    end 

    self.vcam3rdPersonFollowControllerEnv:SetCustomT( 1-t )

    -- if self.inApproachMode == InApproachMode.Entering then 
    --     -- 猫从外部进入通道时:

    -- else 
    --     -- 猫离开通道时:

    --     if t > 0.9 then 


    --         self.isInsideApproach = false
    --     end 
    -- end
end





function PipelineVCamController:CornerDetect()
    local direction = (self._playerFollow.position - self._mainCameraTF.position).normalized + Vector3.up * 0.1
    -- RaycastHit 
    local raycastHit = KTool.GetRaycastHit( self._mainCameraTF.position, direction, 10, -5, QueryTriggerInteraction.Ignore )
    if isNotNull( raycastHit.collider ) then
        return raycastHit.transform.tag ~= "Player"
    else
        return true
    end
end

  

function PipelineVCamController:CloseToPlayer(isCorner)
    local positionOffset = self._vcamDollyComponent.m_AutoDolly.m_PositionOffset
    local pathOffsetY = self._vcamDollyComponent.m_PathOffset.y
    local curValue = Mathf.Lerp(positionOffset, (isCorner and self.cornerPositionOffset or self.normalPositionOffset) * self._vcamDirection, self.closeToPlayerSpeed)
    local value = Mathf.Lerp(pathOffsetY, isCorner and self.cornerPathOffsetY or self.normalPathOffsetY, self.closeToPlayerSpeed)

    -- 此处必须这么赋值
    local AutoDolly = self._vcamDollyComponent.m_AutoDolly
    AutoDolly.m_PositionOffset = curValue
    self._vcamDollyComponent.m_AutoDolly = AutoDolly

    self._vcamDollyComponent.m_PathOffset = Vector3(0, value, 0)

end



function PipelineVCamController:DetectIsLookAtMoving()
    self._movingDetectTimer = self._movingDetectTimer + Time.deltaTime
    if self._movingDetectTimer > self.movingDetectTime then
      if self._movingDetectFrameCount == 0 then
        self._lastLookAtPosition = self.pipelineLookAtPoint.position
        self._movingDetectFrameCount = self._movingDetectFrameCount + 1
      elseif self._movingDetectFrameCount == 1 then
        local distance = Vector3.Distance(self._lastLookAtPosition, self.pipelineLookAtPoint.position)
        self._lookAtIsMoving = distance > self.movingDetectError
        self._movingDetectFrameCount = 0
        self._movingDetectTimer = 0
      end
    end
  end

  

function PipelineVCamController:CalculatePlayerCameraDirection()
    local playerDirection = Vector3.ProjectOnPlane(self._playerFollow.forward, Vector3.up)  -- 角色前进方向
    local cameraDirection = Vector3.ProjectOnPlane(self._mainCameraTF.forward, Vector3.up)  -- 相机朝向
    
    local result = Vector3.Dot(playerDirection, cameraDirection)
    local direction = result > 0 and 1 or -1
    return direction
end

  




return PipelineVCamController

